// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amt1, uint256 amt2, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // first deposit is huge but leaves at least 2 ether of headroom
        uint256 dep1 = bound(amt1, 2 ether, type(uint256).max - 2 ether);
        // second deposit always pushes the sum past 2**256-1 (guaranteed overflow)
        uint256 dep2 = (type(uint256).max - dep1) + 1 + (amt2 % 2 ether);

        vm.deal(actor, dep1 + dep2 + 1 ether);
        vm.startPrank(actor);
        c.Put{value: dep1}(0);
        // On the reference C this overwriting deposit must revert; on the mutant it wraps.
        try c.Put{value: dep2}(0) {} catch {}
        vm.warp(block.timestamp + 1);
        uint256 bal = c.Acc(actor);
        // Collect the entire recorded balance: reference must always succeed and zero it out.
        try c.Collect(bal) {} catch {}
        vm.stopPrank();
        assertTrue(c.Acc(actor) == 0);
    }
}

