pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 a, uint256 b, address actor) public {
        vm.assume(actor != address(0));
        // first deposit large, second small enough to overflow when added
        a = bound(a, 2**255, type(uint256).max);
        b = bound(b, 1, 2**255);
        vm.assume(a + b < a); // wrap condition: overflow will occur in the mutant

        vm.deal(actor, a + b);

        vm.prank(actor);
        c.Put{value: a}(0);
        uint256 afterFirst = c.Acc(actor).balance;

        // second deposit: in the reference this reverts (overflow protection);
        // in the mutant it succeeds and wraps the stored balance.
        vm.prank(actor);
        c.Put{value: b}(0);

        // General rule: a successful (or completed) deposit sequence never
        // decreases the recorded balance below what was already recorded.
        assertTrue(c.Acc(actor).balance >= afterFirst);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 unlockTime, uint256 firstAmount) public {
        address actor = address(0xA11ce);
        // Deal the actor a huge balance so an overflowing deposit is reachable.
        vm.deal(actor, type(uint256).max);

        // First deposit: admissible, must succeed.
        vm.prank(actor);
        c.Put{value: firstAmount}(unlockTime);
        assertTrue(c.Acc(actor).balance == firstAmount && address(c).balance == firstAmount);

        // Bring the recorded balance to the very top of the uint range.
        uint256 remaining = type(uint256).max - firstAmount;
        vm.prank(actor);
        c.Put{value: remaining}(unlockTime);

        uint256 balanceBefore = c.Acc(actor).balance;
        uint256 ethBefore = address(c).balance;

        // Now attempt a further deposit of any size: it can only overflow.
        // Whether it reverts or (in the buggy version) wraps, NO state may change:
        // the recorded balance and the ETH held by the contract must be unchanged.
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 1}(
            abi.encodeWithSignature("Put(uint256)", unlockTime)
        );
        ok; // the call's success is irrelevant; state must be preserved either way

        assertTrue(
            c.Acc(actor).balance == balanceBefore && address(c).balance == ethBefore,
            "state changed across an overflow-attempting deposit"
        );
    }
}

