contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint deposit, uint amount) public payable {
        require(address(this).balance >= deposit, "insufficient");
        uint beforeBalance = c.Acc(address(this))[1];
        c.Put{value: deposit}(0);
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        uint afterBalance = c.Acc(address(this))[1];
        if (!reverted && amount <= afterBalance && beforeBalance + deposit >= c.MinSum() && beforeBalance + deposit >= amount) {
            assert(afterBalance == beforeBalance + deposit - amount);
        } else {
            assert(true);
        }
    }
    receive() external payable {}
}
